    casaDone: "¡La casa quedó más grande y bonita! +100 en el granero y más felicidad.", casaD: "Amplía su casa: un piso más, balcón con flores y después un anexo con bandera. +5 de felicidad y +100 en el granero.", casaMax: "¡Casa completa!", contestT: "Concurso del día en la feria", contestDone: "¡Ganaron el concurso de hoy! Mañana hay otro.", n_casa: "Su casa más grande", n_casaD: "En el Menú: amplía la casa en 2 etapas (piso de arriba con balcón florido, después anexo con bandera). +100 en el granero y +5 de felicidad cada una.", n_storm: "Tormenta y arcoíris", n_stormD: "Con la lluvia caen relámpagos con trueno. Después aparece un arcoíris con una olla de oro cerca de los cultivos: ¡tócala para ganar monedas!", n_contest: "Concurso del día", n_contestD: "Cada día la feria pide un producto: entrégalo y gana un trofeo y muchas monedas. Aparece en Pedidos y en la Feria; los ayudantes ayudan.", casaT: n => `Su casa · nivel ${n}`, potGot: n => `¡Olla de oro! +${n} monedas`, contestWon: n => `¡Trofeo! Ganaron el concurso: +${n} monedas`, contestD: (k, q, c) => `Hoy la feria quiere ${q} ${k}. Premio: ${c} monedas y un trofeo.`, trophies: n => `Trofeos del concurso: ${n}`,
    decorT: "Decorar el mapa", decorHint: "toca el mapa para poner, toca un adorno para quitarlo (devuelve la mitad)", dec_banco: "Banca", dec_poste: "Farol", dec_arvore: "Árbol", dec_flores: "Jardinera", dec_estatua: "Estatua", dec_chafariz: "Pileta", dec_caramanchao: "Glorieta", dec_cata: "Molinete", expedT: "Expedición a la Isla Misteriosa", expedGo: "¡El barco partió a la Isla Misteriosa!", expedOpen: "Abrir el cofre del tesoro", expedGoBtn: "Zarpar", th_pao: "Semana del Pan", th_fruta: "Semana de las Frutas", th_leite: "Semana de la Leche", th_mar: "Semana del Mar", th_doce: "Semana de los Dulces", th_flor: "Semana de las Flores", themeD: "Esta semana estos productos pagan +50% en los pedidos:", n_decor: "Decora el mapa a tu gusto", n_decorD: "En la Tienda: bancas, faroles, árboles, jardineras, estatuas, piletas, glorietas y molinetes. Toca donde quieras ponerlos. Cada 5 adornos dan +1 de felicidad.", n_exped: "Expedición a la Isla Misteriosa", n_expedD: "En el Puerto pesquero: manda el barco por 10 minutos (6 maíces y 2 panes) y vuelve con un cofre de tesoros, monedas y a veces un pez dorado.", n_theme: "Semana temática", n_themeD: "Cada semana un tema (Pan, Frutas, Leche, Mar, Dulces, Flores): los pedidos de esos productos pagan +50%. Aparece en Pedidos.", decorSub: (n, h) => `Adornos puestos: ${n} · +${h} de felicidad (máx. 15)`, expedSub: m => `El barco viaja ${m} minutos y vuelve con tesoros.`, expedBackIn: t => `Vuelve en ${t}`, expedGot: (c, t) => `¡Tesoro de la isla: +${c} monedas y ${t}!`,
    cineT: "Cine al aire libre", cineD: "De noche pasan un dibujo animado en la pantalla del barrio y los vecinos vienen a verlo. +8 de felicidad.", cineGot: "¡Cine listo! Vuelve de noche para ver la función.", n_cine: "Cine al aire libre (nivel 9)", n_cineD: "En el Panel de la ciudad: una pantalla grande en el Barrio Nuevo. De noche pasan un dibujo animado y los vecinos se sientan a verlo. +8 de felicidad.", n_baby: "Nacen bebés", n_babyD: "Con la ciudad feliz (60+), de vez en cuando nace un bebé en una de las casas: la población crece y los bebés pasean con su familia.", n_fire: "Fogatas en invierno", n_fireD: "En las noches de invierno se encienden fogatas en la villa y el barrio.", n_coin: "Monedas en el suelo", n_coinD: "De vez en cuando aparece una moneda brillando cerca de los cultivos: ¡tócala para recogerla!", babyBorn: n => `¡Nació un bebé en la casa de ${n}! 👶`, babiesN: n => `Bebés nacidos: ${n}`, coinFound: n => `¡Encontraste una moneda perdida! +${n}`,
