      h = `<div class="card" style="border:2px solid #9b5de5"><b>🎙️ ${L('cv_pref')} ${esc(cvName(pref.id))}</b><p style="margin:6px 0 0">${esc(L('cvSayHi', ME.name || ''))} ${esc(cvSpeech(S, SH.since))}</p>${C.away && now2 - C.away[0] < 3600000 ? `<p style="margin:6px 0 0;font-weight:800;color:#6b3fa0">🌙 ${L('cvAway', fmtT(C.away[1]), C.away[2])}</p>` : ''}</div>`
      + (C.dem ? `<div class="card" style="border:2px solid #e0533d"><b>📜 ${L('demT', C.dem.c)}</b><br><small>${L('demSub', fmtT(Math.max(1, Math.ceil((C.dem.until - now2) / 1000))))}</small><div class="row" style="gap:6px;margin-top:6px"><button class="btn${C.t >= C.dem.c ? '' : ' gray'}" type="button" data-nbdem="nbPay" ${C.t >= C.dem.c ? '' : 'disabled'} style="flex:1;font-size:14px">${L('demPay')}</button><button class="btn" type="button" data-nbdem="nbRefuse" style="flex:1;font-size:14px;background:#e0533d">${L('demNo')}</button></div></div>` : '')
