function paintMini() { const c = document.getElementById('miniMap'), S = G.S; if (!c || !S) return; const g = c.getContext('2d'), k = c.width / WTOT; g.clearRect(0, 0, c.width, c.height); g.save(); g.translate(-XMIN * k, 0); if (BG) g.drawImage(bgOverview(), XMIN * k, 0, WTOT * k, WH * k); g.fillStyle = 'rgba(0,0,0,.25)'; for (const [kk, Ld] of Object.entries(LANDS)) if (!S.land[kk]) g.fillRect(Ld.r.x * k, Ld.r.y * k, Ld.r.w * k, Ld.r.h * k);
  const vw = innerWidth / CAM.z, vh = innerHeight / CAM.z; g.strokeStyle = '#fff'; g.lineWidth = 3; g.strokeRect((CAM.x - vw / 2) * k, (CAM.y - vh / 2) * k, vw * k, vh * k);
  g.font = '26px sans-serif'; g.textAlign = 'center'; g.textBaseline = 'middle'; for (const e of agenda(S, Date.now())) if (e.w.on && !e.done) { g.fillStyle = 'rgba(255,255,255,.85)'; g.beginPath(); g.arc(e.pos[0] * k, e.pos[1] * k, 17, 0, 6.283); g.fill(); g.fillStyle = '#000'; g.fillText(e.ic, e.pos[0] * k, e.pos[1] * k + 1); }
  const who = [[AV.me, '#ffb020', ME.name]]; if (AV.fr.on && G.mode !== 'solo') who.push([AV.fr, '#9b5de5', AV.fr.name]); for (const [av, col, nm] of who) { const mx = av.x * k, my = av.y * k; g.fillStyle = '#fff'; g.beginPath(); g.arc(mx, my, 15, 0, 6.283); g.fill(); g.fillStyle = col; g.beginPath(); g.arc(mx, my, 11, 0, 6.283); g.fill(); g.fillStyle = '#fff'; g.font = '900 14px Nunito, sans-serif'; g.fillText(String(nm || '?').slice(0, 1).toUpperCase(), mx, my + 1); }
  g.restore(); c.onclick = ev => { const r = c.getBoundingClientRect(), x = XMIN + (ev.clientX - r.left) / r.width * WTOT, y = (ev.clientY - r.top) / r.height * WH; closeSheet(); CAM.z = Math.max(CAM.z, 0.7); CAM.x = x; CAM.y = y; clampCam(); }; }
